export default class Report {
  constructor({ name }) {
    this.name = name;
  }

  toItem() {
    const item = document.createElement("li");
    item.className = "report";
    item.innerHTML = '<span class="report-name"></span>';
    item.querySelector(".report-name").textContent = "Made by the test: " + this.name;
    return item;
  }
}

